import { Server } from 'socket.io'

let ioInstance: Server | null = null

export function setIO(io: Server) {
  ioInstance = io
}

export function getIO(): Server | null {
  return ioInstance
}

import { setIO } from './serverIO'
import { type WebSocketDefinition } from 'wasp/server/webSocket'

export const webSocketFn: WebSocketDefinition = (io, context) => {
  setIO(io)

  io.on('connection', (socket) => {
    const user = socket.data.user
    console.log('A user connected:', user?.username || 'Anonymous')

    socket.on('joinDocument', async ({ documentId }) => {
      socket.join(`document-${documentId}`)
      console.log(`Socket joined room: document-${documentId}`)
    })

    socket.on('leaveDocument', ({ documentId }) => {
      socket.leave(`document-${documentId}`)
      console.log(`Socket left room: document-${documentId}`)
    })

    socket.on('editDocument', async ({ documentId, content }) => {
      if (!user) return

      try {
        const doc = await context.entities.Document.findUnique({
          where: { id: Number(documentId) },
          include: {
            permissions: {
              where: { userId: user.id }
            }
          }
        })

        if (!doc) return

        const isOwner = doc.ownerId === user.id
        const hasEditPermission = doc.permissions.some(p => p.role === 'EDIT')

        if (isOwner || hasEditPermission) {
          // Update database
          await context.entities.Document.update({
            where: { id: Number(documentId) },
            data: { content }
          })

          // Broadcast to all other clients in the document room
          socket.to(`document-${documentId}`).emit('documentEdited', { content })
        }
      } catch (error) {
        console.error('Error handling editDocument:', error)
      }
    })
  })
}

import { HttpError } from 'wasp/server'

export const getDocuments = async (args: any, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  return context.entities.Document.findMany({
    where: {
      OR: [
        { ownerId: context.user.id },
        {
          permissions: {
            some: {
              userId: context.user.id
            }
          }
        }
      ]
    },
    orderBy: {
      updatedAt: 'desc'
    }
  })
}

export const getDocument = async (args: { id: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const document = await context.entities.Document.findUnique({
    where: { id: args.id },
    include: {
      owner: true,
      versions: {
        include: {
          author: true
        },
        orderBy: {
          createdAt: 'asc'
        }
      },
      permissions: {
        include: {
          user: true
        }
      }
    }
  })

  if (!document) {
    throw new HttpError(404, 'Document not found')
  }

  const isOwner = document.ownerId === context.user.id
  const permission = document.permissions.find((p: any) => p.userId === context.user.id)

  if (!isOwner && !permission) {
    throw new HttpError(403, 'Access Denied')
  }

  const userRole = isOwner ? 'OWNER' : permission.role

  return {
    document,
    userRole
  }
}

import { HttpError } from 'wasp/server'
import { getIO } from './serverIO'

export const createDocument = async (args: { title: string }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  return context.entities.Document.create({
    data: {
      title: args.title,
      content: '',
      ownerId: context.user.id
    }
  })
}

export const saveVersion = async (args: { documentId: number, content: string }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const { documentId, content } = args

  const doc = await context.entities.Document.findUnique({
    where: { id: documentId },
    include: {
      permissions: {
        where: { userId: context.user.id }
      }
    }
  })

  if (!doc) {
    throw new HttpError(404, 'Document not found')
  }

  const isOwner = doc.ownerId === context.user.id
  const hasEditPermission = doc.permissions.some((p: any) => p.role === 'EDIT')

  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, 'Access Denied')
  }

  // Create a new Version
  const version = await context.entities.Version.create({
    data: {
      documentId,
      content,
      authorId: context.user.id
    },
    include: {
      author: true
    }
  })

  // Update primary content
  await context.entities.Document.update({
    where: { id: documentId },
    data: { content }
  })

  // Broadcast to other sockets in the room
  const io = getIO()
  if (io) {
    io.to(`document-${documentId}`).emit('documentEdited', { content })
    io.to(`document-${documentId}`).emit('versionSaved', version)
  }

  return version
}

export const restoreVersion = async (args: { documentId: number, versionId: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const { documentId, versionId } = args

  const doc = await context.entities.Document.findUnique({
    where: { id: documentId },
    include: {
      permissions: {
        where: { userId: context.user.id }
      }
    }
  })

  if (!doc) {
    throw new HttpError(404, 'Document not found')
  }

  const isOwner = doc.ownerId === context.user.id
  const hasEditPermission = doc.permissions.some((p: any) => p.role === 'EDIT')

  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, 'Access Denied')
  }

  const version = await context.entities.Version.findUnique({
    where: { id: versionId }
  })

  if (!version || version.documentId !== documentId) {
    throw new HttpError(404, 'Version not found')
  }

  // Update primary content
  await context.entities.Document.update({
    where: { id: documentId },
    data: { content: version.content }
  })

  // Broadcast to all sockets in the room
  const io = getIO()
  if (io) {
    io.to(`document-${documentId}`).emit('documentEdited', { content: version.content })
    io.to(`document-${documentId}`).emit('documentRestored', { content: version.content })
  }

  return version
}

export const shareDocument = async (args: { documentId: number, username: string, role: string }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const { documentId, username, role } = args

  const doc = await context.entities.Document.findUnique({
    where: { id: documentId }
  })

  if (!doc) {
    throw new HttpError(404, 'Document not found')
  }

  if (doc.ownerId !== context.user.id) {
    throw new HttpError(403, 'Only the owner can share the document')
  }

  // Find user to share with
  const shareUser = await context.entities.User.findUnique({
    where: { username }
  })

  if (!shareUser) {
    throw new HttpError(404, 'User not found')
  }

  if (shareUser.id === context.user.id) {
    throw new HttpError(400, 'Cannot share with yourself')
  }

  // Create or update permission
  return context.entities.Permission.upsert({
    where: {
      documentId_userId: {
        documentId,
        userId: shareUser.id
      }
    },
    create: {
      documentId,
      userId: shareUser.id,
      role
    },
    update: {
      role
    }
  })
}

export const revokePermission = async (args: { documentId: number, userId: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized')
  }

  const { documentId, userId } = args

  const doc = await context.entities.Document.findUnique({
    where: { id: documentId }
  })

  if (!doc) {
    throw new HttpError(404, 'Document not found')
  }

  if (doc.ownerId !== context.user.id) {
    throw new HttpError(403, 'Only the owner can revoke permissions')
  }

  return context.entities.Permission.delete({
    where: {
      documentId_userId: {
        documentId,
        userId
      }
    }
  })
}

